using UnityEngine;using UnityEditor;using System.Linq;
public static class InspectMirror {public static string Main(){var m=Object.FindFirstObjectByType<MotorollerController>();return "play="+Application.isPlaying+"; "+string.Join("; ",m.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name.Contains("Mirror")).Select(r=>r.name+" shader="+r.sharedMaterial.shader.name+" doubleSided="+r.sharedMaterial.GetFloat("_DoubleSidedEnable")+" cull="+r.sharedMaterial.GetFloat("_CullMode")+" bounds="+r.bounds))+"; cameras="+string.Join(",",Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Select(c=>c.name+":"+c.nearClipPlane));}}
